theme.css:
/* theme: Rally in the Ruins | Stocks surge upward while political chaos churns below, the page split between market green and embattled red. */
/* mood: good */
/* layout: hero=centered; major-events=banner/grid-3; political-news=numbered/stack; financial-news=stat/stack; entertainment-news=tile/grid-2; sports=outline/grid-2; music-releases=plain/stack; stock-analysis=stat/masonry; outlook=timeline/stack */

.diary-page {
  --paper: #d9f0e0;
  --paper-alt: #c5e6d0;
  --ink: #0d2b1a;
  --ink-soft: #21422f;
  --muted: #3d5c48;
  --accent: #0c6b34;
  --accent-ink: #f2fff6;
  --rule: #a8ccb4;
  --font-display: var(--ff-unbounded), sans-serif;
  --font-body: var(--ff-newsreader), Georgia, serif;
  --font-ui: var(--ff-inter), system-ui, sans-serif;
}

.diary-page[data-hero="centered"] .diary-hero {
  background: linear-gradient(180deg, var(--paper-alt) 0%, var(--paper) 100%);
  border-bottom: 4px solid var(--accent);
  position: relative;
}

.diary-page[data-hero="centered"] .diary-hero::after {
  content: "";
  position: absolute;
  bottom: -4px;
  left: 0;
  right: 0;
  height: 4px;
  background: repeating-linear-gradient(90deg, var(--accent) 0 24px, transparent 24px 32px);
}

.diary-page .diary-hero-inner {
  padding-block: 3rem 4rem;
}

.diary-page .diary-kicker {
  margin-top: 2rem;
  font-size: 0.72rem;
  letter-spacing: 0.28em;
  font-weight: 800;
}

.diary-page .diary-title {
  font-size: clamp(2.4rem, 6vw, 4.5rem);
  font-weight: 800;
  letter-spacing: -0.03em;
  text-transform: uppercase;
  line-height: 1.08;
  max-width: 24ch;
  margin-inline: auto;
}

.diary-page .diary-summary {
  font-family: var(--font-display);
  font-size: clamp(1rem, 1.8vw, 1.25rem);
  font-weight: 500;
  line-height: 1.6;
  letter-spacing: -0.01em;
  max-width: 36rem;
}

.diary-page .diary-theme-note {
  font-size: 0.8rem;
  letter-spacing: 0.04em;
}

.diary-page .diary-theme-name {
  background: var(--accent);
  color: var(--accent-ink);
  border-radius: 0;
  padding: 0.2rem 0.8rem;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  font-size: 0.72rem;
}

.diary-page .diary-crumbs a {
  font-weight: 600;
}

.diary-page .diary-toc {
  background: var(--paper);
  border-bottom-color: var(--accent);
}

.diary-page .diary-toc-list {
  gap: 0;
  border-left: 0;
}

.diary-page .diary-toc-link {
  border-left: 0;
}

.diary-page .diary-toc-link.is-active {
  border-left-color: var(--accent);
  color: var(--accent);
  font-weight: 700;
}

.diary-page .diary-toc-number {
  font-weight: 800;
}

.diary-page .diary-section {
  border-top: 1px solid var(--rule);
  position: relative;
}

.diary-page .diary-section::before {
  content: "";
  position: absolute;
  top: 3rem;
  left: 0;
  width: 3px;
  height: 2.2rem;
  background: var(--accent);
}

.diary-page .diary-section-head {
  margin-left: 1.25rem;
  margin-bottom: 2rem;
}

.diary-page .diary-section-number {
  font-weight: 800;
  letter-spacing: 0.16em;
  font-size: 0.72rem;
}

.diary-page .diary-section-title {
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: -0.02em;
}

.diary-page .diary-prose {
  font-size: 1.08rem;
  line-height: 1.72;
}

.diary-page .diary-prose a {
  font-weight: 700;
  border-bottom-width: 2px;
  letter-spacing: 0.02em;
}

.diary-page .diary-prose strong {
  color: var(--ink);
  font-weight: 700;
}

.diary-page .diary-prose blockquote {
  border-left-color: var(--accent);
  border-left-width: 4px;
}

.diary-page .diary-prose ul > li::before {
  background: var(--accent);
  height: 3px;
}

.diary-page .diary-prose ol > li::marker {
  font-weight: 800;
}

.diary-page .diary-card--banner .diary-card-inner {
  gap: 0;
  overflow: hidden;
  border: 2px solid var(--accent);
  border-radius: 0.25rem;
  background: var(--paper);
}

.diary-page .diary-card--banner .diary-card-title {
  background: linear-gradient(135deg, var(--accent) 0%, color-mix(in srgb, var(--accent) 70%, #052e15) 100%);
  color: var(--accent-ink);
  font-size: 1rem;
  font-weight: 700;
  letter-spacing: -0.01em;
  text-transform: uppercase;
  padding: 0.9rem 1.25rem;
  line-height: 1.3;
}

.diary-page .diary-card--banner .diary-card-body {
  padding: 1.25rem;
  font-size: 1rem;
}

.diary-page .diary-card--banner .diary-card-thread {
  margin: 0.75rem 1.25rem 1.25rem;
}

.diary-page [data-section="political-news"] .diary-stories--stack {
  max-width: 42rem;
}

.diary-page [data-section="political-news"] .diary-card--numbered .diary-card-index {
  font-size: 2.2rem;
  font-weight: 800;
  line-height: 1;
  color: var(--accent);
}

.diary-page [data-section="political-news"] .diary-card--numbered .diary-card-inner {
  column-gap: 1.1rem;
}

.diary-page [data-section="political-news"] .diary-card-title {
  font-size: 1.3rem;
  font-weight: 700;
  letter-spacing: -0.01em;
  line-height: 1.25;
}

.diary-page [data-section="financial-news"] .diary-stories--stack {
  max-width: 46rem;
  gap: 1.5rem;
}

.diary-page [data-section="financial-news"] .diary-card--stat .diary-card-inner {
  border-top: 4px solid var(--accent);
  padding-top: 1.25rem;
}

.diary-page [data-section="financial-news"] .diary-card-figure {
  font-size: clamp(2.5rem, 8cqi, 4rem);
  font-weight: 800;
  letter-spacing: -0.03em;
  line-height: 1.05;
}

.diary-page [data-section="financial-news"] .diary-card-title {
  font-size: 1.5rem;
  font-weight: 700;
}

.diary-page [data-section="entertainment-news"] .diary-card--tile .diary-card-inner {
  background: var(--paper-alt);
  border-left: 4px solid var(--accent);
  padding: 1.25rem 1.25rem 1.25rem 1.5rem;
}

.diary-page [data-section="entertainment-news"] .diary-card-title {
  font-size: 1.15rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.01em;
}

.diary-page [data-section="entertainment-news"] .diary-card-body {
  font-size: 1rem;
}

.diary-page [data-section="sports"] .diary-card--outline .diary-card-inner {
  border: 2px solid var(--rule);
  border-radius: 0.375rem;
  padding: 1.25rem;
}

.diary-page [data-section="sports"] .diary-card-title {
  font-size: 1.1rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.01em;
  line-height: 1.3;
  color: var(--ink);
}

.diary-page [data-section="sports"] .diary-card-body {
  font-size: 0.98rem;
}

.diary-page [data-section="sports"] .diary-card--outline .diary-card-inner:has(.diary-card-thread) {
  border-color: var(--accent);
}

.diary-page [data-section="music-releases"] .diary-stories--stack {
  max-width: 50rem;
}

.diary-page [data-section="music-releases"] .diary-card--plain {
  border-bottom: 1px dashed var(--rule);
  padding-bottom: 1.25rem;
}

.diary-page [data-section="music-releases"] .diary-card--plain:last-child {
  border-bottom: 0;
}

.diary-page [data-section="music-releases"] .diary-card-title {
  font-size: 1.35rem;
  font-weight: 700;
  letter-spacing: -0.01em;
}

.diary-page [data-section="music-releases"] .diary-card-body {
  font-size: 1rem;
}

.diary-page [data-section="stock-analysis"] .diary-stories--masonry {
  columns: 2 17rem;
  column-gap: 1.25rem;
}

.diary-page [data-section="stock-analysis"] .diary-card--stat .diary-card-inner {
  border-top: 3px solid var(--accent);
  padding-top: 0.9rem;
}

.diary-page [data-section="stock-analysis"] .diary-card-figure {
  font-size: clamp(1.8rem, 7cqi, 2.75rem);
  font-weight: 800;
  letter-spacing: -0.02em;
}

.diary-page [data-section="stock-analysis"] .diary-card-title {
  font-size: 1.25rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.01em;
  line-height: 1.25;
}

.diary-page [data-section="stock-analysis"] .diary-card-body {
  font-size: 0.95rem;
  line-height: 1.6;
}

.diary-page [data-section="outlook"] .diary-card--timeline .diary-card-inner {
  padding-left: 1.5rem;
}

.diary-page [data-section="outlook"] .diary-card--timeline .diary-card-inner::before {
  background: var(--rule);
  width: 3px;
}

.diary-page [data-section="outlook"] .diary-card--timeline .diary-card-inner::after {
  background: var(--accent);
  width: 0.6rem;
  height: 0.6rem;
  left: 0.05rem;
  top: 0.5rem;
  box-shadow: 0 0 0 4px var(--paper);
}

.diary-page [data-section="outlook"] .diary-card-title {
  font-size: 1.15rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.02em;
  line-height: 1.25;
}

.diary-page [data-section="outlook"] .diary-card-body {
  font-size: 1rem;
}

.diary-page .diary-card-thread {
  border-radius: 0;
  border-width: 2px;
  font-weight: 700;
  letter-spacing: 0.03em;
  text-transform: uppercase;
  font-size: 0.68rem;
}

.diary-page .diary-card-thread:hover {
  background: var(--accent);
  color: var(--accent-ink);
}

.diary-page .diary-markets-wrap {
  margin-bottom: 2.5rem;
}

.diary-page .diary-markets-label {
  font-size: 0.68rem;
  font-weight: 800;
  letter-spacing: 0.18em;
}

.diary-page .diary-markets {
  grid-template-columns: repeat(auto-fill, minmax(10rem, 1fr));
  gap: 0.6rem;
}

.diary-page .diary-spark {
  background: var(--paper-alt);
  border: 1px solid var(--rule);
  border-radius: 0.125rem;
  padding: 0.6rem 0.75rem 0.5rem;
}

.diary-page .diary-spark.is-up {
  border-left: 3px solid var(--accent);
}

.diary-page .diary-spark.is-down {
  border-left: 3px solid var(--ink);
}

.diary-page .diary-spark-value {
  font-weight: 800;
}

.diary-page .diary-spark-change {
  font-weight: 700;
}

.diary-page .diary-spark.is-up .diary-spark-change {
  color: var(--accent);
}

.diary-page .diary-spark.is-down .diary-spark-change {
  color: var(--ink);
}

.diary-page .diary-spark-line polyline {
  stroke: var(--accent);
  stroke-width: 2;
  fill: none;
}

.diary-page .diary-spark.is-down .diary-spark-line polyline {
  stroke: var(--ink);
}

.diary-page .diary-footer {
  border-top-color: var(--accent);
  font-weight: 500;
}

.diary-page .diary-footer a {
  font-weight: 800;
  letter-spacing: 0.02em;
}

.diary-page .diary-footer a:hover {
  color: var(--accent);
}

@media (min-width: 1024px) {
  .diary-page .diary-toc {
    margin-top: 2rem;
  }

  .diary-page .diary-toc-list {
    border-left: 3px solid var(--rule);
  }

  .diary-page .diary-toc-link {
    border-left: 3px solid transparent;
    margin-left: -3px;
  }

  .diary-page .diary-toc-link.is-active {
    border-left-color: var(--accent);
    background: linear-gradient(90deg, color-mix(in srgb, var(--accent) 12%, transparent) 0%, transparent 70%);
  }
}

@media (prefers-reduced-motion: no-preference) {
  .diary-page .diary-card {
    transition: transform 160ms ease-out, box-shadow 160ms ease-out;
  }

  .diary-page .diary-card--elevated:hover,
  .diary-page .diary-card--tile:hover {
    transform: translateY(-2px);
    box-shadow: 0 4px 12px color-mix(in srgb, var(--accent) 20%, transparent);
  }

  .diary-page .diary-card--outline:hover {
    border-color: var(--accent);
  }
}
